SELECT activity_id, activity_title, status, publish_status, start_at, end_at, participants, conversion
FROM agent_v3_marketing_activity_view
WHERE agent_v3_marketing_activity_view.store_id = ANY(:allowedStoreIds) AND (status IN ('***', '***', '***', '***')) LIMIT 100;

SELECT project_id, project_name, project_type, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 82) LIMIT 100;

SELECT project_id, project_name, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 81) LIMIT 100;

SELECT project_id, project_name, project_type, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 78) LIMIT 100;

SELECT COUNT(DISTINCT staff_id) AS staff_count
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (status = '***') LIMIT 1;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (status = '***') LIMIT 100;

SELECT staff_id, staff_name, created_at
FROM agent_v3_staff_profile_view WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) ORDER BY created_at DESC
LIMIT 10;

SELECT COUNT(DISTINCT customer_id) AS customer_count
FROM ask_data_customer_lifecycle_view
WHERE ask_data_customer_lifecycle_view.store_id = ANY(:allowedStoreIds) AND (churn_risk_level IN ('***', '***')) LIMIT 1;

SELECT customer_id, customer_name_masked, ltv_tier, churn_risk_level, computed_at
FROM ask_data_customer_lifecycle_view
WHERE ask_data_customer_lifecycle_view.store_id = ANY(:allowedStoreIds) AND (churn_risk_level IN ('***', '***')) LIMIT 100;

SELECT COUNT(DISTINCT customer_id) AS customer_count, SUM(total_paid_amount) AS total_paid_amount
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (member_level = '***') LIMIT 1;

SELECT transfer_id, transfer_no, product_count
FROM ask_data_transfer_status_view WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) ORDER BY product_count DESC
LIMIT 10;
